@pytest.mark.parametrize("reverse", [False, True]) def test_dated_pool_uses_canonical_monthly_targets_without_eligibility_leak(compute_db, reverse): db, _ = compute_db unit, people = clear_fixture(db) promoted, colleague = people["Safe Member"], people["Spare One"] for person in people.values(): person.call_level = "3RD_CALL" for posting in person.postings: posting.posting_type = "3RD_CALL" senior = Person(canonical_name="Senior A", call_level="4TH_CALL") reserve = Person(canonical_name="Senior B", call_level="4TH_CALL") db.add_all([senior, reserve]) db.add(MemberCallLevelChange( person=promoted, call_level="4TH_CALL", effective_from=date(2026, 5, 16) )) for person in (senior, reserve): db.add(PersonPosting( person=person, unit=unit, posting_type="4TH_CALL", starts_on=date(2026, 5, 1), source="unit_board", )) _, rules = get_phase_one_rules(db) rules.duty_rules.extend([ day_rule("AUDIT_POOL", ["3RD_CALL", "4TH_CALL"]), day_rule("AUDIT_THIRD", ["3RD_CALL"]), day_rule("AUDIT_FOURTH", ["4TH_CALL"]), ]) early_pool = day_slot(db, unit, 5, "AUDIT_POOL", None) early_senior = day_slot(db, unit, 6, "AUDIT_FOURTH", "4TH_CALL") third = day_slot(db, unit, 8, "AUDIT_THIRD", "3RD_CALL") late_pool = day_slot(db, unit, 20, "AUDIT_POOL", None) db.commit() rows = [early_pool, early_senior, third, late_pool] if reverse: rows.reverse() slots = {str(row.id): row for row in rows} context = candidate_context(db, "2026-05", rules=rules) # An impossible senior preference before promotion must not become a candidate. preferences = {f"{early_senior.id}:{promoted.id}": -2_000_000} expected = {str(early_pool.id): str(promoted.id), str(early_senior.id): str(senior.id), str(third.id): str(colleague.id), str(late_pool.id): str(promoted.id)} preferences.update({f"{sid}:{person}": -1_000_000 for sid, person in expected.items()}) result = solve_month(db, context, slots, mode="preferences", seconds=5, preferences=preferences) > assert result["choices"] == expected E AssertionError: assert {'9d2559db-c3...fd3c9dbf6688'} == {'9d2559db-c3...fd3c9dbf6688'} E E Omitting 3 identical items, use -vv to show E Differing items: E {'a6a3be0f-19b7-41f4-98ae-2a7d5299c93a': '98bdd447-1353-47a8-936e-0d698ce771ef'} != {'a6a3be0f-19b7-41f4-98ae-2a7d5299c93a': 'c786b573-fd9e-4fc8-8aac-4e4e9c8e98ca'} E Use -v to get more diff
